    setInterval(() => {
      this.seconds += 1;
      console.log(this.seconds);
    }, 1000);
  }
}
new Timer().start();
```

Now `this` inside the callback correctly refers to the `Timer` instance, and `this.seconds` increases by 1 each tick as expected.

